const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Point([15.05, 12.33]).buffer(5000); // Digangali, Chad, with a 5km buffer

    const date1_start = '2021-09-03'; // +/- 15 days from Sep 18, 2021
    const date1_end = '2021-10-03';

    const date2_start = '2022-10-08'; // +/- 15 days from Oct 23, 2022
    const date2_end = '2022-11-08';

    // Function to mask clouds in Sentinel-2 SR data.
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000)
                  .select('B3', 'B11') // Select only bands used for MNDWI
                  .copyProperties(image, ['system:time_start']);
    }

    // Function to calculate MNDWI
    function calculateMNDWI(image) {
      const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI'); // Green (B3), SWIR1 (B11)
      return image.addBands(mndwi);
    }

    // 2. Data Acquisition & Check for Period 1 (2021)
    let collection1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                        .filterBounds(geometry)
                        .filterDate(date1_start, date1_end)
                        .map(maskS2clouds)
                        .map(calculateMNDWI);

    const size1 = await collection1.size().getInfo();
    if (size1 === 0) {
      console.log("No images found for 2021 period.");
      console.log("C1");
      return;
    }
    const img1 = collection1.median();

    // Calculate valid pixels for 2021
    const count1 = await img1.select('MNDWI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 20, // Sentinel-2 SWIR1 is 20m resolution
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    if (count1 === 0) {
      console.log(`2021 Images: ${size1}`);
      console.log("No valid pixels after masking for 2021 period.");
      console.log("C2");
      return;
    }

    // 2. Data Acquisition & Check for Period 2 (2022)
    let collection2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                        .filterBounds(geometry)
                        .filterDate(date2_start, date2_end)
                        .map(maskS2clouds)
                        .map(calculateMNDWI);

    const size2 = await collection2.size().getInfo();
    if (size2 === 0) {
      console.log("No images found for 2022 period.");
      console.log("C1");
      return;
    }
    const img2 = collection2.median();

    // Calculate valid pixels for 2022
    const count2 = await img2.select('MNDWI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 20,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    if (count2 === 0) {
      console.log(`2021 Images: ${size1}, Pixels: ${count1}`);
      console.log(`2022 Images: ${size2}`);
      console.log("No valid pixels after masking for 2022 period.");
      console.log("C2");
      return;
    }

    // 3. Water Extent Calculation
    const waterMask1 = img1.select('MNDWI').gt(0.1); // MNDWI > 0.1 for water classification
    const waterMask2 = img2.select('MNDWI').gt(0.1);

    // Calculate area in square kilometers
    const pixelArea = ee.Image.pixelArea().divide(1e6); // Convert m^2 to km^2

    const waterArea1 = await waterMask1.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 20,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    const waterArea2 = await waterMask2.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 20,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    // 4. Validation & Final Answer
    if (waterArea1 === null || waterArea2 === null) {
      console.log("C3");
      return;
    }

    console.log(`2021 Images: ${size1}, Pixels: ${count1}`);
    console.log(`2022 Images: ${size2}, Pixels: ${count2}`);
    console.log(`2021 Water Extent: ${waterArea1.toFixed(2)} km²`);
    console.log(`2022 Water Extent: ${waterArea2.toFixed(2)} km²`);

    if (waterArea2 > waterArea1) {
      console.log("A"); // Yes, surface water extent increased
    } else {
      console.log("B"); // No, surface water extent did not increase
    }

  } catch (error) {
    console.error("Analysis failed: ", error);
    console.log("D"); // Catch any unexpected errors like invalid band names or memory issues.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
